def _lookup(payload, key):
    if key in payload:
        return payload[key]
    lk = str(key).lower()
    for k, v in payload.items():
        if str(k).lower() == lk:
            return v
    raise KeyError(key)

def _lookup_opt(payload, key):
    try:
        return _lookup(payload, key), True
    except KeyError:
        return None, False

def decide(rule, spec, payload):
    kind = str(rule.get("kind", "key")).lower() if isinstance(rule, dict) else "key"
    if kind == "key":
        marker = rule.get("key", "flag") if isinstance(rule, dict) else "flag"
        # presence check, case-insensitive
        mk = str(marker).lower()
        for k in payload.keys():
            if str(k).lower() == mk:
                return "b"
        return "a"
    return "a"

# aliases for integration join compatibility
def diagnose(rule, spec, payload):
    return decide(rule, spec, payload)

def select_mode(rule, spec, payload):
    return decide(rule, spec, payload)

def get_mode(rule, spec, payload):
    return decide(rule, spec, payload)

def mode(rule, spec, payload):
    return decide(rule, spec, payload)

def operands(rule, spec, payload, md):
    m = str(md).lower() if isinstance(md, str) else md
    # normalize single-letter mode; accept 'a'/'b', 'mode a', etc.
    if m not in ("a", "b"):
        ml = str(m).lower()
        if "b" in ml:
            m = "b"
        else:
            m = "a"
    kind = str(rule["kind"]).lower() if isinstance(rule, dict) and "kind" in rule else "key"
    if kind == "key":
        lk = spec["list_keys"][m] if m in spec["list_keys"] else spec["list_keys"][m.lower()] if isinstance(spec.get("list_keys"), dict) else None
        if lk is None:
            # fallback case-insensitive spec lookup
            for k, v in spec["list_keys"].items():
                if str(k).lower() == str(m).lower():
                    lk = v
                    break
        vals, _ = _lookup_opt(payload, lk)
        if vals is None:
            return []
        return list(vals)
    if kind in ("threshold", "prefix"):
        vals, found = _lookup_opt(payload, "vals")
        if not found:
            # try any list value fallback
            for v in payload.values():
                if isinstance(v, list):
                    return list(v)
            return []
        return list(vals)
    items, found = _lookup_opt(payload, "items")
    if not found:
        return []
    if m == "a":
        return list(items) if isinstance(items, list) else list(items) if hasattr(items, "__iter__") and not isinstance(items, dict) else list(items.values()) if isinstance(items, dict) else [items]
    else:
        if isinstance(items, dict):
            return list(items.values())
        return list(items)

